[CmdletBinding()]param()
$ErrorActionPreference='Continue';$repoRoot=(Resolve-Path(Join-Path $PSScriptRoot '..\..')).Path
function RunScript([string]$name,[string]$file){Write-Output "`n== $name ==";& powershell -NoProfile -ExecutionPolicy Bypass -File (Join-Path $PSScriptRoot $file);if($LASTEXITCODE -ne 0){throw "$name failed"}}
try{RunScript 'Repository checks' 'check-repo.ps1';RunScript 'F04 regression' 'check-f04.ps1';RunScript 'Ensure backend' 'ensure-local-backend-f03.ps1';RunScript 'F05 mobile checks' 'check-mobile-f05.ps1';RunScript 'F05 publish and Feed smoke' 'smoke-mobile-content-f05.ps1';RunScript 'Final backend status' 'status-local-backend-f03.ps1';foreach($file in @('reports\F05_EXECUTION_REPORT.md','reports\F05_UI_REVIEW_CHECKLIST.md','reports\F05_PUBLISH_RETURN_FIX_REPORT.md','docs\references\BACKEND_API_CHANGELOG.md')){if(-not(Test-Path -LiteralPath (Join-Path $repoRoot $file) -PathType Leaf)){throw "Missing F05 document: $file"}};Write-Output 'F05 Flutter content publish interaction check passed';exit 0}catch{Write-Error $_;exit 1}
